    class PaletteText extends TextView {
        final int baseColor;
        PaletteText(int color){super(MainActivity.this);baseColor=fg(color);}
        @Override protected void onAttachedToWindow(){super.onAttachedToWindow();int surface=0;View current=this;
            while(current!=null){android.graphics.drawable.Drawable d=current.getBackground();int value=Color.TRANSPARENT;
                if(d instanceof android.graphics.drawable.GradientDrawable){android.content.res.ColorStateList c=((android.graphics.drawable.GradientDrawable)d).getColor();if(c!=null)value=c.getDefaultColor();}
                else if(d instanceof android.graphics.drawable.ColorDrawable)value=((android.graphics.drawable.ColorDrawable)d).getColor();
                if(Color.alpha(value)>0){surface=value;break;}android.view.ViewParent parent=current.getParent();current=parent instanceof View?(View)parent:null;
            }
            int brightness=(Color.red(surface)*299+Color.green(surface)*587+Color.blue(surface)*114)/1000;
            setTextColor(isLight()?(Color.alpha(baseColor)==0?0xff171717:baseColor):(Color.alpha(surface)>0&&brightness>130?0xff111111:baseColor));
        }
    }
