    long parseAmount(String s){if(s.trim().isEmpty())return 0; long n=new BigDecimal(s.trim()).movePointRight(2).longValueExact();if(n<0||n>=100000000000L)throw new IllegalArgumentException();return n;}
    long totalFor(Calendar start){Calendar end=(Calendar)start.clone();end.add(Calendar.MONTH,1);return store.personalSpent(start.getTimeInMillis(),end.getTimeInMillis(),key(start));}
    void checkLimitWarning(Runnable after){Calendar now=Calendar.getInstance();now.set(Calendar.DAY_OF_MONTH,1);now.set(Calendar.HOUR_OF_DAY,0);now.set(Calendar.MINUTE,0);now.set(Calendar.SECOND,0);now.set(Calendar.MILLISECOND,0);long limit=prefs.getLong("limit_"+key(now),0);long spent=totalFor(now);if(limit>0&&spent>=limit&&!isFinishing()){AlertDialog warning=new AlertDialog.Builder(this).setTitle("Monthly limit reached").setMessage("You've spent "+money(spent)+" this month, reaching your "+money(limit)+" limit. Review your transactions to keep track.").setPositiveButton("Got it",null).create();warning.setOnDismissListener(d->{if(!isFinishing()&&!isDestroyed())after.run();});showStyled(warning);}else after.run();}
    boolean canGoNextMonth(){Calendar now=Calendar.getInstance();int selected=month.get(Calendar.YEAR)*12+month.get(Calendar.MONTH),current=now.get(Calendar.YEAR)*12+now.get(Calendar.MONTH);return selected<current;}
    boolean canGoPreviousMonth(){Calendar previous=(Calendar)month.clone();previous.add(Calendar.MONTH,-1);try(Cursor c=store.getReadableDatabase().rawQuery("SELECT 1 FROM transactions WHERE date>=? AND date<? LIMIT 1",new String[]{""+previous.getTimeInMillis(),""+month.getTimeInMillis()})){return c.moveToFirst();}}
