    void loadStorageUsage(TextView total,TextView detail){
        new Thread(()->{
            try{
                android.os.storage.StorageManager volumes=(android.os.storage.StorageManager)getSystemService(Context.STORAGE_SERVICE);
                java.util.UUID uuid=volumes.getUuidForPath(getFilesDir());
                android.app.usage.StorageStatsManager manager=(android.app.usage.StorageStatsManager)getSystemService(Context.STORAGE_STATS_SERVICE);
                android.app.usage.StorageStats stats=manager.queryStatsForPackage(uuid,getPackageName(),android.os.Process.myUserHandle());
                String all=android.text.format.Formatter.formatFileSize(this,stats.getAppBytes()+stats.getDataBytes());
                String breakdown="App "+android.text.format.Formatter.formatFileSize(this,stats.getAppBytes())+"  •  Data "+android.text.format.Formatter.formatFileSize(this,stats.getDataBytes())+" (includes cache)";
                runOnUiThread(()->{if(!isFinishing()&&!isDestroyed()&&total.isAttachedToWindow()){total.setText(all);detail.setText(breakdown);}});
            }catch(Exception e){runOnUiThread(()->{if(!isFinishing()&&!isDestroyed()&&total.isAttachedToWindow()){total.setText("Unavailable");detail.setText("Storage information could not be loaded.");}});}
        }).start();
    }
    void handleBack(){if(showingPayees)showProfile();else if(!showingHome || trackerPage || fuelPage || emiPage)showHome();else super.onBackPressed();}
    void updateSystemBack(){
        if(android.os.Build.VERSION.SDK_INT<33)return;
        boolean intercept=showingPayees || !showingHome || trackerPage || fuelPage || emiPage;
        if(intercept && !systemBackRegistered){if(systemBackCallback==null)systemBackCallback=()->handleBack();getOnBackInvokedDispatcher().registerOnBackInvokedCallback(android.window.OnBackInvokedDispatcher.PRIORITY_DEFAULT,systemBackCallback);systemBackRegistered=true;}
        else if(!intercept && systemBackRegistered){getOnBackInvokedDispatcher().unregisterOnBackInvokedCallback(systemBackCallback);systemBackRegistered=false;}
    }
    @Override public void onBackPressed(){handleBack();}
